/** Lookup over AMFI's scheme master (public/data/schemes.json, generated by scripts/build-scheme-index.mjs). */
import { familyName, schemeKey } from "../finance/categorize";

export interface SchemeIndexFile {
  source: string;
  generatedAt: string;
  categories: string[];
  amcs: string[];
  /** [code, isinGrowth, isinReinvest, fullName, categoryIdx, amcIdx, nav, navDate] */
  schemes: [number, string, string, string, number, number, number, string][];
}

export interface SchemeInfo {
  code: number;
  isin: string;
  isinReinvest: string;
  name: string;
  category: string;
  amc: string;
  nav: number;
  navDate: string;
}

export class SchemeIndex {
  readonly generatedAt: string;
  private byIsin = new Map<string, SchemeInfo>();
  private all: SchemeInfo[] = [];

  constructor(file: SchemeIndexFile) {
    this.generatedAt = file.generatedAt;
    for (const [code, isin, isinR, name, ci, ai, nav, navDate] of file.schemes) {
      const info: SchemeInfo = {
        code,
        isin,
        isinReinvest: isinR,
        name,
        category: file.categories[ci] ?? "",
        amc: file.amcs[ai] ?? "",
        nav,
        navDate,
      };
      this.all.push(info);
      if (isin) this.byIsin.set(isin, info);
      if (isinR) this.byIsin.set(isinR, info);
    }
  }

  get size() {
    return this.all.length;
  }

  lookupIsin(isin: string | null | undefined): SchemeInfo | null {
    if (!isin) return null;
    return this.byIsin.get(isin.toUpperCase()) ?? null;
  }

  /** Best-effort match by scheme name when the CAS has no ISIN. */
  lookupName(name: string, plan: "Direct" | "Regular", option: "Growth" | "IDCW"): SchemeInfo | null {
    const key = schemeKey(name);
    const candidates = this.all.filter((s) => schemeKey(s.name) === key);
    return pick(candidates, plan, option);
  }

  /** The same scheme in the other plan (direct <-> regular), same option. */
  counterpart(info: SchemeInfo, plan: "Direct" | "Regular", option: "Growth" | "IDCW"): SchemeInfo | null {
    const key = schemeKey(info.name);
    const fam = familyName(info.name).toLowerCase();
    const candidates = this.all.filter((s) => s.amc === info.amc && s.code !== info.code && (schemeKey(s.name) === key || familyName(s.name).toLowerCase() === fam));
    return pick(candidates, plan, option);
  }
}

function pick(candidates: SchemeInfo[], plan: "Direct" | "Regular", option: "Growth" | "IDCW"): SchemeInfo | null {
  const planRe = plan === "Direct" ? /\bdirect\b/i : /\bregular\b|^(?!.*\bdirect\b)/i;
  const optRe = option === "IDCW" ? /idcw|dividend/i : /growth/i;
  const scored = candidates
    .map((c) => ({ c, s: (planRe.test(c.name) ? 2 : 0) + (optRe.test(c.name) ? 1 : 0) + (/bonus|retail|institutional/i.test(c.name) ? -2 : 0) }))
    .sort((a, b) => b.s - a.s || b.c.navDate.localeCompare(a.c.navDate));
  const best = scored[0];
  if (!best || best.s < 2) return null;
  return best.c;
}

let cached: Promise<SchemeIndex | null> | null = null;
/** Browser loader (lazy, cached). Resolves null if the file can't be fetched – the app keeps working. */
export function loadSchemeIndex(): Promise<SchemeIndex | null> {
  if (!cached) {
    cached = fetch("/data/schemes.json")
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(String(r.status)))))
      .then((f: SchemeIndexFile) => new SchemeIndex(f))
      .catch(() => null);
  }
  return cached;
}
